const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define the point geometry (longitude corrected from -81.81.970... to -81.97068)
  const point = ee.Geometry.Point([-81.97068176434179, 38.07594286088219]);

  // Helper function to get least cloudy Landsat 5 image in a date range
  function getLeastCloudyImage(startDate, endDate) {
    const collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(point)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUD_COVER', 80)); // Filter out very cloudy images

    // Sort by cloud cover and get the first image
    const sorted = collection.sort('CLOUD_COVER');
    return sorted.first();
  }

  // 2. Define initial date ranges (3 months around target dates)
  let startRange = ['1984-06-17', '1984-12-17'];
  let endRange = ['2009-03-02', '2009-09-02'];

  // Try to get images, with fallback extensions if needed
  let startImg = getLeastCloudyImage(startRange[0], startRange[1]);
  let endImg = getLeastCloudyImage(endRange[0], endRange[1]);

  // Check if collections are empty by checking image ID
  let startCount = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(point)
    .filterDate(startRange[0], startRange[1])
    .size();
  let endCount = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(point)
    .filterDate(endRange[0], endRange[1])
    .size();

  // Get the counts as numbers
  let startCountNum = startCount.getInfo();
  let endCountNum = endCount.getInfo();

  console.log(`Start period (${startRange[0]} to ${startRange[1]}) images: ${startCountNum}`);
  console.log(`End period (${endRange[0]} to ${endRange[1]}) images: ${endCountNum}`);

  // If either count is 0, try extending the date range by 2 years
  if (startCountNum === 0) {
    startRange = ['1984-01-01', '1986-12-31'];
    startImg = getLeastCloudyImage(startRange[0], startRange[1]);
    startCount = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(point)
      .filterDate(startRange[0], startRange[1])
      .size();
    startCountNum = startCount.getInfo();
    console.log(`Extended start period images: ${startCountNum}`);
  }
  if (endCountNum === 0) {
    endRange = ['2008-01-01', '2010-12-31'];
    endImg = getLeastCloudyImage(endRange[0], endRange[1]);
    endCount = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(point)
      .filterDate(endRange[0], endRange[1])
      .size();
    endCountNum = endCount.getInfo();
    console.log(`Extended end period images: ${endCountNum}`);
  }

  // If still no images, output C1
  if (startCountNum === 0 || endCountNum === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Cloud masking function for Landsat 5
  function maskClouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4)); // Cloud and cloud shadow bits
    return image.updateMask(cloudMask.not());
  }

  // Apply cloud masking
  startImg = maskClouds(startImg);
  endImg = maskClouds(endImg);

  // 4. Compute NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('ndvi');
    return image.addBands(ndvi);
  }
  startImg = addNDVI(startImg);
  endImg = addNDVI(endImg);

  // 5. Extract NDVI values at the point
  const startVal = startImg.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: point,
    scale: 30,
    bestEffort: true
  }).get('ndvi');
  const endVal = endImg.reduceRegion({
    reducer: ee.Reducer.first(),
    geometry: point,
    scale: 30,
    bestEffort: true
  }).get('ndvi');

  // Get the values as numbers
  let startNdvi, endNdvi;
  try {
    startNdvi = startVal.getInfo();
    endNdvi = endVal.getInfo();
  } catch (e) {
    console.log('Error extracting pixel values.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Start NDVI: ${startNdvi}`);
  console.log(`End NDVI: ${endNdvi}`);

  // 6. Check for valid pixels (null means masked out)
  if (startNdvi === null || endNdvi === null) {
    console.log('One or both pixels are invalid (cloud masked).');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Determine deforestation based on NDVI drop and initial forest condition
  // Assuming forest if NDVI > 0.6, and significant drop > 0.2
  const isForestStart = startNdvi > 0.6;
  const ndviDrop = startNdvi - endNdvi;
  const isSignificantDrop = ndviDrop > 0.2;

  console.log(`NDVI drop: ${ndviDrop.toFixed(3)}`);
  console.log(`Initially forested? ${isForestStart}`);

  // 8. Final decision
  if (isForestStart && isSignificantDrop) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
